package com.brightloop.invoice;
import com.brightloop.catalog.Product;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="invoice_lines") public class InvoiceLine{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="invoice_id",nullable=false) Invoice invoice;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) Product product;@Column(nullable=false,length=255) String description;@Column(nullable=false) int quantity;@Column(name="unit_price",nullable=false,precision=12,scale=2) BigDecimal unitPrice;@Column(name="tax_rate",nullable=false,precision=12,scale=4) BigDecimal taxRate;@Column(name="tax_amount",nullable=false,precision=12,scale=2) BigDecimal taxAmount;@Column(name="line_total",nullable=false,precision=14,scale=2) BigDecimal lineTotal;
 protected InvoiceLine(){}public InvoiceLine(Invoice i,Product p,String d,int q,BigDecimal u,BigDecimal r,BigDecimal t,BigDecimal total){invoice=i;product=p;description=d;quantity=q;unitPrice=u;taxRate=r;taxAmount=t;lineTotal=total;}public Long getId(){return id;}public String getDescription(){return description;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getTaxRate(){return taxRate;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getLineTotal(){return lineTotal;}public Product getProduct(){return product;}
}
